func init() {
	shellEscapePattern = regexp.MustCompile(`[^\w@%+=:,./-]`)
}

func shellEscape(s string) string {
	if len(s) == 0 {
		return "''"
	}
	if shellEscapePattern.MatchString(s) {
		return "'" + strings.Replace(s, "'", "'\"'\"'", -1) + "'"
	}

	return s
}

